import{_ as a,o,c as t,a2 as r}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/pt/whatsapp-detalhe.png",n="/pro-agent-hub-installer/capturas/pt/msteams-detalhe.png",h=JSON.parse('{"title":"Integrações","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/integracoes.md","filePath":"pt/interface/integracoes.md","lastUpdated":1787856241000}'),p={name:"pt/interface/integracoes.md"};function m(i,e,d,c,u,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="integracoes" tabindex="-1">Integrações <a class="header-anchor" href="#integracoes" aria-label="Permalink to &quot;Integrações&quot;">​</a></h1><p>Levam um agente ou time para onde as pessoas já conversam, em vez de pedir que elas entrem na plataforma.</p><p>As duas integrações funcionam do mesmo jeito: a plataforma expõe um <strong>webhook</strong>, o serviço externo chama esse endereço a cada mensagem recebida, o agente responde e a plataforma devolve a resposta pelo mesmo canal.</p><p>Em ambas, você vincula <strong>um agente ou um time</strong> — nunca os dois.</p><h2 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h2><p><img src="'+s+'" alt="whatsapp-detalhe"></p><p>A conexão é via <strong>Evolution API</strong>, que é quem fala com o WhatsApp de fato. O cadastro guarda o endereço do servidor, a chave da API e o nome da instância.</p><p>Depois de salvar, copie o <strong>endereço do webhook</strong> da tela e configure-o na Evolution API. Sem esse passo, a integração fica cadastrada e nunca recebe nada — é o erro mais comum.</p><p><strong>O token do webhook é obrigatório.</strong> Ele é o que distingue uma mensagem vinda da sua Evolution API de qualquer requisição que encontre o endereço. Sem token conferido, o webhook seria uma porta aberta.</p><h3 id="duas-opcoes-que-mudam-o-comportamento" tabindex="-1">Duas opções que mudam o comportamento <a class="header-anchor" href="#duas-opcoes-que-mudam-o-comportamento" aria-label="Permalink to &quot;Duas opções que mudam o comportamento&quot;">​</a></h3><p><strong>Modo público.</strong> Ligado, todas as mensagens são tratadas como o usuário de serviço da plataforma, em vez de criar um usuário por número de telefone. É o que se quer num atendimento aberto ao público; é o que <strong>não</strong> se quer quando cada pessoa deve ter o próprio histórico.</p><p><strong>Responder erros.</strong> Ligado, uma falha de processamento vira uma mensagem para quem escreveu. Você pode substituir o texto cru da exceção por um texto seu — e deveria: mensagem de erro técnica no WhatsApp de um cliente não ajuda ninguém.</p><h2 id="microsoft-teams" tabindex="-1">Microsoft Teams <a class="header-anchor" href="#microsoft-teams" aria-label="Permalink to &quot;Microsoft Teams&quot;">​</a></h2><p><img src="'+n+'" alt="msteams-detalhe"></p><p>A conexão é por um <strong>bot registrado no Azure</strong>. O cadastro guarda o App ID, a senha do bot e, opcionalmente, o tenant.</p><p>O caminho é o inverso do WhatsApp: primeiro registre o bot no Azure, depois aponte o <em>messaging endpoint</em> dele para o webhook que esta tela mostra.</p><p>Vale saber antes de começar: o registro do bot é feito no portal do Azure, fora da plataforma, e costuma depender de quem administra o tenant da empresa. É a parte demorada.</p>',17)])])}const f=a(p,[["render",m]]);export{h as __pageData,f as default};
